/** Lane-specific base win rate (wins/games in that lane); falls back to the card's primary-lane rate. */
export function getLaneWinRate(card: Card, lane: Lane): number {
  const s = LANE_STATS[card.id]?.[lane];
  return s && s[1] > 0 ? s[0] / s[1] : card.laneWinRate;
}

/** Games played in a specific lane (0 if not legal there). */
export function getLaneGames(card: Card, lane: Lane): number {
  return LANE_STATS[card.id]?.[lane]?.[1] ?? 0;
}

// Get all cards valid for a given lane
export function getCardsForLane(lane: Lane): Card[] {
  return CARDS.filter((c) => c.lanes.includes(lane));
}

// Get card by ID
export function getCardById(id: string): Card | undefined {
  return CARDS.find((c) => c.id === id);
}

// Shuffle array (Fisher-Yates)
export function shuffle<T>(array: T[]): T[] {
  const arr = [...array];
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}
